style.css:
@-moz-document domain("roblox.com") {
.custom-animation-container {
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 400px;
        height: 150px;
        background-color: black;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
        z-index: 9999;
    }

    .custom-animation-container .text {
        position: absolute;
        font-family: 'Arial', sans-serif;
        font-size: 4em;
        color: white;
        opacity: 0;
        white-space: nowrap;
        text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    }

    .custom-animation-container .ok {
        animation: fadeInOutOk 5s infinite;
    }

    .custom-animation-container .broken {
        animation: fadeInOutBroken 5s infinite;
    }

    @keyframes fadeInOutOk {
        0% { opacity: 1; }
        40% { opacity: 1; }
        50% { opacity: 0; }
        100% { opacity: 0; }
    }

    @keyframes fadeInOutBroken {
        0% { opacity: 0; }
        50% { opacity: 0; }
        60% { opacity: 1; }
        90% { opacity: 1; }
        100% { opacity: 0; }
    }
}
